def compute(vars):
    cost_2018 = vars["v1"]
    cost_2019 = vars["v2"]
    average_cost = (cost_2018 + cost_2019) / 2
    return {
        "value": average_cost,
        "trace": {
            "cost_2018": cost_2018,
            "cost_2019": cost_2019,
            "average_cost": average_cost,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
